"""Validated extraction followed by deterministic human-review routing."""
import re
from .validation import validate_reply, InvalidResponse
from .provider import ProviderError
import shlex
from .prompt import PROMPT

REQUIRED = ('request_id','request_date','requester','team','system','environment',
            'permission','business_purpose','start_date','end_date','manager')

def route(extraction, document_id, message=""):
    attack = re.search(r"SYSTEM OVERRIDE:.*", message, re.I | re.S)
    if attack or any("override" in i.lower() for i in extraction["issues"]):
        if attack and attack[0] not in extraction["supporting_quotes"]:
            extraction["supporting_quotes"].append(attack[0])
        if not any("override" in i.lower() for i in extraction["issues"]):
            extraction["issues"].append("instruction-override attempt")
        return "review", "IT Service Desk", "inspect-message"
    issues = extraction['issues']
    if extraction['kind'] == 'withdrawal' and extraction['request_id'] and extraction['request_date']:
        return 'review','IT Service Desk','confirm-withdrawal'
    identifier = re.fullmatch(r'(IT-\d+)\.json', document_id)
    mismatch = identifier and extraction['request_id'] and identifier[1] != extraction['request_id']
    reversed_dates = (extraction['start_date'] and extraction['end_date']
                      and extraction['start_date'] > extraction['end_date'])
    if mismatch and not any('mismatch' in i for i in issues):
        issues.append('identifier mismatch: ' + document_id + ' / ' + extraction['request_id'])
    if reversed_dates and not any('start_date' in i for i in issues):
        issues.append('start_date after end_date')
    if (extraction['kind'] in ('other', None) or any(extraction[k] is None for k in REQUIRED)
            or mismatch or reversed_dates or any('conflict' in i.lower() for i in issues)):
        return 'needs-information','IT Service Desk','clarify'
    if extraction['environment'] == 'production' or extraction['permission'] in ('write','admin'):
        return 'review','Security Review','review-risk-then-owner'
    return 'review','System Owner','review-request'

def error_record(document, category, explanation, origin='mock'):
    return dict(document_id=document.document_id, source_sha256=document.source_sha256,
                extraction=None,status='error',owner='IT Service Desk',next_action='retry-extraction',
                error=dict(category=category,message=explanation,
                           retry_command='python -m access_requests retry ' + shlex.quote(document.document_id)),
                response_source=origin)

def process(document, provider, settings=None):
    from .config import Settings
    settings = settings or Settings()
    try:
        reply = (provider.extract_source(document.message) if hasattr(provider,'extract_source')
                 else provider.extract(settings.prompt + '\n' + document.message))
        extraction = validate_reply(reply, document.message)
    except ProviderError:
        # Exception payloads may contain credentials; never retain them.
        return error_record(document,'provider','Provider unavailable; retry this document.',provider.response_source)
    except InvalidResponse:
        category = ('refusal' if reply.get('status') == 'refused' or reply.get('refusal') else
                    'incomplete' if reply.get('status') != 'completed' else 'invalid-response')
        return error_record(document,category,category + ': retry extraction.',provider.response_source)
    status, owner, action = route(extraction, document.document_id, document.message)
    if owner == 'System Owner':
        match = re.search(r'Complete staging/read requests go to (.+?) with status review', settings.policy)
        if match:
            owner = match[1]
    return dict(document_id=document.document_id, source_sha256=document.source_sha256,
                extraction=extraction,status=status,owner=owner,next_action=action,
                error=None,response_source=reply.get('response_source',provider.response_source))

class Dispatcher:
    def __init__(self):
        self.documents = {}
        self.results = {}

    def run(self, document, provider):
        self.documents[document.document_id] = document
        self.results[document.document_id] = process(document, provider)
        return self.results[document.document_id]

    def retry(self, document_id, provider):
        return self.run(self.documents[document_id], provider)
"""Read source facts exclusively from the decoded message; identify original bytes."""
from dataclasses import dataclass
import hashlib
import json
from pathlib import Path

@dataclass(frozen=True)
class Document:
    document_id: str
    source_sha256: str
    message: str
    raw: bytes

def read_document(path):
    path = Path(path)
    raw = path.read_bytes()
    export = json.loads(raw.decode('utf-8'))
    if not isinstance(export.get('message'), str):
        raise ValueError('export message must be a string')
    return Document(path.name, hashlib.sha256(raw).hexdigest(), export['message'], raw)
"""Admit only completed, schema-valid responses with exact source quotations."""
import json
import re
from pathlib import Path
from jsonschema import Draft202012Validator

SCHEMA = json.loads((Path(__file__).resolve().parents[1] / 'snapshot.schema.json').read_text())
VALIDATOR = Draft202012Validator(SCHEMA)

class InvalidResponse(Exception):
    pass

def validate_reply(reply, message):
    if not isinstance(reply, dict) or reply.get('status') != 'completed':
        raise InvalidResponse('refused or incomplete response')
    if reply.get('refusal'):
        raise InvalidResponse('refusal')
    try:
        extraction = json.loads(reply['output_text'])
        VALIDATOR.validate(extraction)
    except (KeyError, TypeError, ValueError, __import__('jsonschema').ValidationError) as error:
        raise InvalidResponse('malformed extraction: ' + type(error).__name__) from None
    for field in ('request_date', 'start_date', 'end_date'):
        value = extraction[field]
        if value is not None and re.fullmatch(r'[0-9]{4}-[0-9]{2}-[0-9]{2}', value) is None:
            raise InvalidResponse('date does not use YYYY-MM-DD: ' + field)
    if any(quote not in message for quote in extraction['supporting_quotes']):
        raise InvalidResponse('supporting quote is not an exact substring of the decoded message')
    return extraction
"""Credential-free producing configuration used for provenance and cache keys."""
from dataclasses import dataclass, field, asdict
import hashlib
import json
from .prompt import PROMPT, POLICY_PATH
from .validation import SCHEMA

def digest(value):
    return hashlib.sha256(value.encode()).hexdigest()

@dataclass(frozen=True)
class Settings:
    provider: str = 'mock'
    model: str = 'gpt-4.1-mini-2025-04-14'
    endpoint: str = 'https://api.openai.com/v1/responses'
    timeout: float = 30
    max_output_tokens: int = 2048
    prompt: str = PROMPT
    schema: dict = field(default_factory=lambda: json.loads(json.dumps(SCHEMA)))
    policy: str = field(default_factory=lambda: POLICY_PATH.read_text())

    def public(self):
        return asdict(self)

    @property
    def fingerprint(self):
        return digest(json.dumps(self.public(),sort_keys=True,separators=(',',':')))

    @property
    def policy_version(self):
        return digest(self.policy)
"""Bounded scheduling; SQLite transactions never span a provider invocation."""
from concurrent.futures import ThreadPoolExecutor
import json
from .config import Settings
from .intake import read_document, Document
from .pipeline import process

class Engine:
    def __init__(self, store, settings=None, workers=1, lease_seconds=None):
        self.store = store
        self.settings = settings or Settings()
        self.workers=max(1,min(workers,32))
        self.lease_seconds=lease_seconds if lease_seconds is not None else self.settings.timeout+30

    def execute(self, job_id, provider):
        job=self.store.claim(job_id,self.lease_seconds)
        if job is None:
            return self.store.job_result(job_id)
        settings=Settings(**json.loads(job['settings']))
        document=Document(job['document_id'],job['source_sha256'],json.loads(job['raw'])['message'],job['raw'])
        selected=provider.for_document(document.document_id) if hasattr(provider,'for_document') else provider
        result=process(document,selected,settings)
        return self.store.finish(job,result)

    def run(self, document, provider, force=False):
        return self.execute(self.store.register(document,self.settings,force),provider)

    def intake(self, paths, provider):
        jobs=[self.store.register(read_document(path),self.settings) for path in paths]
        with ThreadPoolExecutor(self.workers) as pool:
            return list(pool.map(lambda job: self.execute(job,provider),jobs))

    def retry(self, document_id, provider):
        return self.run(self.store.document(document_id),provider,force=True)

    def refresh(self, document_id, provider):
        return self.retry(document_id,provider)

    def resume(self, provider):
        jobs=[job['job_id'] for job in self.store.pending()]
        with ThreadPoolExecutor(self.workers) as pool:
            return list(pool.map(lambda job: self.execute(job,provider),jobs))

